-- RN Master native-format/case-study pilot import. Preserves matrix, cloze, highlight, bow-tie, SATA and MC formats.
begin;
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set13-Case','RN Master Set 13 unfolding case study','A 4-month-old infant born at term is brought to the emergency department by a parent. The infant has had a runny nose and cough for 3 days. A rapid test is positive for respiratory syncytial virus (RSV). Nurses'' notes, 0200: Parent reports the infant took only 1 oz (30 mL) of formula in the past 4 hours and has had 2 wet diapers in 12 hours. Parent also reports that at home the infant "stopped breathing for a few seconds" once. Copious thick nasal secretions. Nasal flaring, subcostal and intercostal retractions, and head bobbing. Expiratory wheezes and fine crackles bilaterally. Anterior fontanel slightly sunken. Mucous membranes dry. Capillary refill 3 seconds. Infant is irritable, alternating with periods of lethargy. Vital signs: T 100.9°F (38.3°C) rectal, HR 172/min, RR 68/min, SpO2 88% on room air. Weight 6.4 kg.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set14-Case','RN Master Set 14 unfolding case study','A 52-year-old client is 2 days postoperative after open reduction and internal fixation of an ankle fracture sustained in a fall. On admission, the client reported drinking "6 to 8 beers a day" for years. The last drink was about 52 hours ago. Nurses'' notes, 2200: Client is agitated, pulling at the IV, and says, "Get those bugs off the wall!" Oriented to person only. Coarse tremor of both hands. Profuse sweating. Reports nausea. Clinical Institute Withdrawal Assessment for Alcohol (CIWA-Ar) score: 22. Vital signs: T 100.9°F (38.3°C), HR 128/min, RR 24/min, BP 178/102 mm Hg, SpO2 96% on room air. Laboratory results: glucose 68 mg/dL, magnesium 1.3 mg/dL (1.7–2.2), potassium 3.2 mEq/L (3.5–5.0), AST 142 units/L, ALT 70 units/L. A dextrose-containing IV fluid has been prescribed.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set15-Case','RN Master Set 15 unfolding case study','A 58-year-old client weighing 90 kg is admitted with an acute pulmonary embolism. The provider prescribes IV heparin per the facility''s weight-based protocol. Baseline aPTT 30 seconds, platelets 230,000/mm³. Heparin protocol: Bolus 80 units/kg IV, then infuse 18 units/kg/hr. Premixed bag: heparin 25,000 units in 500 mL D5W (50 units/mL). Bolus vial: heparin 5,000 units/mL. Check aPTT 6 hours after starting and 6 hours after every rate change. Adjustments by aPTT: below 45 seconds, rebolus 40 units/kg and increase by 2 units/kg/hr; 46–70 seconds (therapeutic), no change; 71–90 seconds, decrease by 2 units/kg/hr; above 90 seconds, hold the infusion for 1 hour, then decrease by 3 units/kg/hr and notify the provider. Nurses'' notes, 6 hours after starting heparin: Client reports that their gums bled when brushing teeth. Urine in the bedside urinal is pink-tinged. No headache; neurologically intact. Vital signs: HR 96/min, BP 128/76 mm Hg, RR 20/min, SpO2 95% on 2 L/min nasal cannula. Laboratory results: aPTT 98 seconds, platelets 210,000/mm³, hemoglobin 13.1 g/dL (baseline 13.6).','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set16-Case','RN Master Set 16 unfolding case study','At 0700, an RN on a medical-surgical unit receives a five-client assignment and works with one LPN/VN and one assistive personnel (AP). Handoff report: Room 1: 68-year-old, postoperative day 1 after bowel resection. Stable. Morphine PCA; pain 3/10. Needs ambulation 3 times today and scheduled oral medications. Room 2: 55-year-old with COPD admitted overnight. SpO2 87% on 2 L/min nasal cannula, RR 28/min, using accessory muscles, speaking in short phrases. Room 3: 80-year-old with advanced dementia. Stable. Needs feeding assistance and incontinence care. Ate 50% of dinner. Room 4: 45-year-old with newly diagnosed type 1 diabetes, going home this afternoon. Has not yet received insulin teaching. Fasting glucose 188 mg/dL. Room 5: 72-year-old with heart failure. Stable. Weight up 0.2 kg from yesterday. Due for IV furosemide at 0900, subcutaneous enoxaparin, and oral medications. Morning potassium 3.1 mEq/L.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set17-Case','RN Master Set 17 unfolding case study','An 82-year-old client is on postoperative day 2 after a hip hemiarthroplasty. The client has mild cognitive impairment but lived alone independently before admission. Yesterday the client was alert and oriented x3. Nurses'' notes, 0200: Client is restless, pulling at the IV, and trying to climb over the raised side rails, saying, "I have to go home and feed my cat." Oriented to person only. Eyeglasses and hearing aids are in the bedside drawer. The urinary catheter was removed yesterday at 1400; the client has not voided in 8 hours, and a bladder scan shows 650 mL. Morse Fall Scale score: 85. Medications given this evening: diphenhydramine 50 mg PO at 2200 (PRN for sleep) and hydromorphone 1 mg IV at 2300. Vital signs: T 100.6°F (38.1°C), HR 102/min, RR 20/min, BP 118/70 mm Hg, SpO2 91% on room air.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set18-Case','RN Master Set 18 unfolding case study','A 29-year-old client, gravida 2 para 1, at 31 weeks'' gestation comes to labor and delivery reporting "tightening" of the abdomen and low back pain for 3 hours. She also reports burning with urination for 2 days. Nurses'' notes, 1600: Contractions every 5 minutes, lasting 40 seconds, palpating moderate. Sterile speculum and cervical exam: 2 cm dilated, 80% effaced; membranes intact. Fetal fibronectin: positive. Group B streptococcus status: unknown. Fetal heart rate baseline 145/min with moderate variability and accelerations; no decelerations. Vital signs: T 99.1°F (37.3°C), HR 92/min, RR 18/min, BP 118/72 mm Hg. Urinalysis: positive nitrites and leukocyte esterase.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set19-Case','RN Master Set 19 unfolding case study','A 64-year-old client with long-standing, poorly controlled hypertension arrives at the emergency department 45 minutes after the sudden onset of severe chest pain. The client describes the pain as "tearing" and says it moves through to the back between the shoulder blades. Nurses'' notes, 1130: Diaphoretic and anxious. Pain rated 10/10. New diastolic murmur heard at the left sternal border. Right radial pulse strong; left radial pulse weaker. Lungs clear. Vital signs: BP right arm 196/108 mm Hg, left arm 150/88 mm Hg; HR 112/min; RR 24/min; SpO2 96% on room air; T 98.4°F (36.9°C). Diagnostics: 12-lead ECG shows sinus tachycardia without ST elevation. Troponin within normal limits. CT angiography confirms a Stanford type A aortic dissection involving the ascending aorta.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set20-Case','RN Master Set 20 unfolding case study','A 19-year-old client dove into a shallow lake and is brought to the emergency department 40 minutes later, immobilized with a cervical collar. CT shows a C6 vertebral fracture with spinal cord injury. Nurses'' notes, 1500: Alert and oriented x3. Weak elbow flexion bilaterally; no movement of the hands, trunk, or legs. Absent sensation below the upper chest. Breathing is shallow and mainly abdominal. Vital capacity 1.2 L (predicted 4.5 L). Skin below the injury is warm, dry, and flushed. Priapism present. Abdomen soft. Focused ultrasound (FAST) exam negative for internal bleeding. Vital signs: T 97.0°F (36.1°C), HR 48/min, RR 24/min, BP 78/44 mm Hg (MAP 55), SpO2 93% on 2 L/min nasal cannula. Laboratory results: hemoglobin 14.2 g/dL, lactate 1.6 mmol/L.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set21-Case','RN Master Set 21 unfolding case study','A 79-year-old resident of a long-term care facility with type 2 diabetes is admitted after 3 days of decreased oral intake during a urinary tract infection. The resident takes metformin and glipizide. Nurses'' notes, 0900: Lethargic, disoriented to place and time. Mucous membranes dry and cracked. Poor skin turgor over the sternum. Respirations regular, not deep; no fruity breath odor. Urine dark and cloudy. Vital signs: T 100.8°F (38.2°C), HR 118/min, RR 20/min, BP 92/54 mm Hg, SpO2 95% on room air. Weight 64 kg. Laboratory results: glucose 986 mg/dL, serum osmolality 362 mOsm/kg (275–295), sodium 149 mEq/L, potassium 4.9 mEq/L, BUN 58 mg/dL, creatinine 2.1 mg/dL, arterial pH 7.36, HCO3 22 mEq/L, serum ketones trace. Urinalysis: positive nitrites and leukocytes.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set13-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Tachypnea, hypoxemia, and increased work of breathing indicate respiratory distress. Apnea is a serious risk in young infants with RSV. Poor intake with decreased urine output and a sunken fontanel indicate dehydration. Rhinorrhea is expected.','Pediatrics','Adult Health','{"segments":[{"id":"s1","text":"RR 68/min","correct":false},{"id":"s2","text":"SpO2 88% on room air","correct":true},{"id":"s3","text":"Subcostal and intercostal retractions with head bobbing","correct":true},{"id":"s4","text":"Reported brief pause in breathing","correct":false},{"id":"s5","text":"1 oz of formula in 4 hours","correct":false},{"id":"s6","text":"2 wet diapers in 12 hours","correct":true},{"id":"s7","text":"Slightly sunken anterior fontanel","correct":true},{"id":"s8","text":"Runny nose for 3 days","correct":false}]}','RNMaster-Set13-Case','1'),
('Set13-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects respiratory distress or dehydration. Respiratory','','','Respiratory distress: nasal flaring, retractions, head bobbing. Dehydration: sunken fontanel, decreased wet diapers, dry mucosa. Infants show increased work of breathing through flaring, retractions, and head bobbing. Tachypnea and nasal congestion interfere with feeding, and fluid losses increase, leading to dehydration.','Pediatrics','Adult Health','{"columns":[{"id":"c1","label":"Dehydration"}],"rows":[{"id":"r1","label":"Nasal flaring","correct":"c1"},{"id":"r2","label":"Subcostal and intercostal retractions","correct":"c1"},{"id":"r3","label":"Head bobbing","correct":"c1"},{"id":"r4","label":"Sunken anterior fontanel","correct":"c1"},{"id":"r5","label":"2 wet diapers in 12 hours","correct":"c1"},{"id":"r6","label":"Dry mucous membranes","correct":"c1"}]}','RNMaster-Set13-Case','2'),
('Set13-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The infant is experiencing ___1___, and the priority problem is ___2___.','','','gas exchange and ineffective airway clearance A positive RSV test with wheezing, crackles, and copious secretions in an infant indicates bronchiolitis. Infants are obligate nose breathers, so secretions impair ventilation. Hypoxemia is the most immediate threat.','Pediatrics','Adult Health','{"blanks":[{"id":"b1","options":["RSV bronchiolitis with respiratory distress","bacterial epiglottitis","croup","cystic fibrosis exacerbation"],"correct":"RSV bronchiolitis with respiratory distress"},{"id":"b2","options":["impaired gas exchange and ineffective airway clearance","risk for injury","altered growth","knowledge deficit"],"correct":"impaired gas exchange and ineffective airway clearance"}]}','RNMaster-Set13-Case','3'),
('Set13-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate, based on current bronchiolitis guidelines? Select all that apply. ☐','Nasal suctioning, especially before feedings ☐|Supplemental oxygen to maintain SpO2 at or above about 90% ☐|IV or nasogastric fluids if the infant cannot feed adequately ☐|Contact and droplet precautions ☐|Continuous cardiorespiratory monitoring and pulse oximetry ☐|Routine nebulized albuterol and oral corticosteroids ☐|Routine antibiotics','A,B,C,D,E','Bronchiolitis care is supportive: suctioning, oxygen, hydration, isolation, and monitoring (especially for apnea in young infants). AAP guidelines advise against routine bronchodilators, corticosteroids, and antibiotics because they do not improve outcomes in viral bronchiolitis.','Pediatrics','Management of Care','{}','RNMaster-Set13-Case','4'),
('Set13-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which action should the nurse take first?','Suction the infant''s nares|Administer nebulized albuterol|Obtain an accurate weight on a scale|Start an IV line','A','Clearing the nasal passages is the first step to open the airway in an infant who is an obligate nose breather. It often improves oxygenation and work of breathing. Oxygen is applied immediately after if SpO2 remains low.','Pediatrics','Adult Health','{}','RNMaster-Set13-Case','5'),
('Set13-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twelve hours later, the nurse reassesses the infant. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: SpO2 94%, RR 44, mild retractions, 5 wet diapers, taking 3 oz feeds. Follow-up: apnea with bradycardia. Better oxygenation, less work of breathing, and adequate intake and output show improvement. Apnea of 20 seconds or longer with bradycardia is a life-threatening event requiring stimulation, possible ventilatory support, and immediate provider notification. Answers: Set 14: Mental Health','Pediatrics','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"SpO2 94% on 1 L/min nasal cannula","correct":"c1"},{"id":"r2","label":"RR 44/min","correct":"c1"},{"id":"r3","label":"Mild subcostal retractions only","correct":"c1"},{"id":"r4","label":"5 wet diapers in the past 12 hours","correct":"c1"},{"id":"r5","label":"Taking 3 oz of formula every 3 hours","correct":"c1"},{"id":"r6","label":"Apnea lasting 20 seconds with HR dropping to 80/min","correct":"c1"}]}','RNMaster-Set13-Case','6'),
('Set14-RN-15','Psychosocial Integrity','Therapeutic communication','matrix_grid','For each nurse statement, indicate whether it is therapeutic or nontherapeutic. Nontherapeuti','','','Therapeutic: open-ended exploring, making observations, therapeutic silence. Nontherapeutic: "why" questions, false reassurance, giving advice. Open-ended statements, observations, and silence encourage expression. "Why" questions put clients on the defensive, reassurance dismisses feelings, and advice undermines the client''s autonomy.','Mental Health','Mental Health','{"columns":[{"id":"c1","label":"Therapeutic"}],"rows":[{"id":"r1","label":"\"Tell me more about what happened.\"","correct":"c1"},{"id":"r2","label":"\"Why did you do that?\"","correct":"c1"},{"id":"r3","label":"\"Don''t worry. Everything will be fine.\"","correct":"c1"},{"id":"r4","label":"\"You seem upset today.\"","correct":"c1"},{"id":"r5","label":"\"If I were you, I would leave him.\"","correct":"c1"}]}','','0'),
('Set14-RN-20','Psychosocial Integrity','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Hallucinations, disorientation, autonomic hyperactivity, and a CIWA-Ar score above 20 indicate severe withdrawal. Hypoglycemia and hypomagnesemia increase the risk of seizures and dysrhythmias. SpO2 is acceptable.','Mental Health','Mental Health','{"segments":[{"id":"s1","text":"Visual hallucinations of bugs on the wall","correct":true},{"id":"s2","text":"Oriented to person only","correct":false},{"id":"s3","text":"HR 128/min","correct":false},{"id":"s4","text":"BP 178/102 mm Hg","correct":false},{"id":"s5","text":"T 100.9°F (38.3°C)","correct":false},{"id":"s6","text":"CIWA-Ar score 22","correct":true},{"id":"s7","text":"Glucose 68 mg/dL","correct":true},{"id":"s8","text":"Magnesium 1.3 mg/dL","correct":true},{"id":"s9","text":"SpO2 96% on room air","correct":false}]}','RNMaster-Set14-Case','1'),
('Set14-RN-21','Psychosocial Integrity','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects autonomic hyperactivity or a perceptual or cognitive disturbance. Perceptual/co Autonomic','','','Autonomic: tachycardia, hypertension, diaphoresis. Perceptual/cognitive: hallucinations, disorientation, agitated pulling at lines. Loss of alcohol''s depressant effect causes rebound sympathetic activation and CNS excitation. Delirium tremens combines both with disturbed consciousness, perception, and cognition.','Mental Health','Mental Health','{"columns":[{"id":"c1","label":"gnitive"}],"rows":[{"id":"r1","label":"HR 128/min","correct":"c1"},{"id":"r2","label":"BP 178/102 mm Hg","correct":"c1"},{"id":"r3","label":"Profuse sweating","correct":"c1"},{"id":"r4","label":"Seeing bugs on the wall","correct":"c1"},{"id":"r5","label":"Oriented to person only","correct":"c1"},{"id":"r6","label":"Pulling at the IV line","correct":"c1"}]}','RNMaster-Set14-Case','2'),
('Set14-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is most likely experiencing ___1___, and is at greatest risk for ___2___.','','','injury, and cardiovascular collapse Delirium tremens typically begins 48–96 hours after the last drink, with disorientation, hallucinations, and autonomic instability. Mortality is significant without treatment. The timing and autonomic signs fit withdrawal rather than a primary psychosis.','Mental Health','Adult Health','{"blanks":[{"id":"b1","options":["alcohol withdrawal delirium (delirium tremens)","a primary psychotic disorder","postoperative pain","hepatic encephalopathy"],"correct":"alcohol withdrawal delirium (delirium tremens)"},{"id":"b2","options":["seizures, injury, and cardiovascular collapse","constipation","wound dehiscence","hypothermia"],"correct":"seizures, injury, and cardiovascular collapse"}]}','RNMaster-Set14-Case','3'),
('Set14-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Benzodiazepine (such as lorazepam) per CIWA-Ar protocol ☐|Thiamine IV ☐|Magnesium and potassium replacement ☐|Seizure and fall precautions ☐|A quiet, well-lit room with frequent reorientation ☐|Haloperidol as the only treatment for withdrawal ☐|Applying restraints as the first intervention','A,B,C,D,E','Benzodiazepines are first-line treatment for withdrawal. Thiamine prevents Wernicke encephalopathy, and electrolytes are corrected. Safety measures and a calm, well-lit environment reduce misperceptions. Antipsychotics alone lower the seizure threshold and do not treat withdrawal. Restraints are a last resort.','Mental Health','Pharmacology','{}','RNMaster-Set14-Case','4'),
('Set14-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','Before starting the prescribed dextrose-containing IV fluid, which medication should the nurse administer?','Thiamine|Folic acid only|Naloxone|Potassium chloride IV push','A','Clients with chronic alcohol use are often thiamine deficient. Glucose metabolism uses thiamine, so giving dextrose first can precipitate or worsen Wernicke encephalopathy. Thiamine is given before or with glucose. Potassium is never given by IV push.','Mental Health','Pharmacology','{}','RNMaster-Set14-Case','5'),
('Set14-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twelve hours after treatment begins, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: CIWA-Ar 6, HR 92, oriented x3, BP 134/82, no hallucinations. Follow-up: oversedation with RR 8. Lower CIWA-Ar scores, stable vital signs, and clear orientation show effective withdrawal management. Excessive sedation with respiratory depression indicates benzodiazepine oversedation, which requires holding doses, airway support, and provider notification. Answers: Set 15: Pharmacology and Dosage Calculation','Mental Health','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"CIWA-Ar score 6","correct":"c1"},{"id":"r2","label":"HR 92/min","correct":"c1"},{"id":"r3","label":"Oriented to person, place, and time","correct":"c1"},{"id":"r4","label":"BP 134/82 mm Hg","correct":"c1"},{"id":"r5","label":"No hallucinations reported","correct":"c1"},{"id":"r6","label":"Difficult to arouse with RR 8/min after the last lorazepam dose","correct":"c1"}]}','RNMaster-Set14-Case','6'),
('Set15-RN-8','Safety and Infection Control','Crushing medications','matrix_grid','A client has difficulty swallowing pills. For each medication, indicate whether it is generally safe to crush or should not be crushed.','','','Safe: plain acetaminophen, metoprolol tartrate IR. Do not crush: XL, ER, and enteric-coated tablets, and sublingual nitroglycerin. Crushing extended-release products causes dose dumping, and crushing enteric coatings exposes the stomach to irritation or destroys the drug. Sublingual tablets are designed to dissolve under the tongue. The nurse consults the pharmacist or provider for alternatives.','Pharmacology','Safety & Infection Control','{"columns":[{"id":"c1","label":"Safe to crush"},{"id":"c2","label":"Do not crush"}],"rows":[{"id":"r1","label":"Metoprolol succinate extended-release (XL) tablet","correct":"c2"},{"id":"r2","label":"Enteric-coated aspirin","correct":"c1"},{"id":"r3","label":"Nitroglycerin sublingual tablet","correct":"c1"},{"id":"r4","label":"Plain acetaminophen tablet","correct":"c1"},{"id":"r5","label":"Metoprolol tartrate immediate-release tablet","correct":"c1"},{"id":"r6","label":"Nifedipine extended-release (ER) tablet","correct":"c1"}]}','','0'),
('Set15-RN-20','Reduction of Risk Potential','Case study: Recognize cues','highlight','Highlight (circle) the findings at the 6-hour check that require follow-up.','','','The aPTT is above the therapeutic range, and gum bleeding and hematuria are signs of excessive anticoagulation. Platelets, BP, neurological status, and hemoglobin are stable.','Pharmacology','Adult Health','{"segments":[{"id":"s1","text":"aPTT 98 seconds","correct":true},{"id":"s2","text":"Gums bled when brushing teeth","correct":true},{"id":"s3","text":"Pink-tinged urine","correct":true},{"id":"s4","text":"Platelets 210,000/mm³","correct":false},{"id":"s5","text":"BP 128/76 mm Hg","correct":false},{"id":"s6","text":"Neurologically intact","correct":false},{"id":"s7","text":"Hemoglobin 13.1 g/dL","correct":false}]}','RNMaster-Set15-Case','1'),
('Set15-RN-21','Pharmacological and Parenteral Therapies','Case study: Analyze cues','cloze_dropdown','Complete the sentences by choosing from the lists of options. The initial bolus volume drawn from the 5,000 units/mL vial was ___1___. The initial infusion rate was ___2___.','','','Infusion: 18 units × 90 kg = 1,620 units/hr ÷ 50 units/mL = 32.4 mL/hr.','Pharmacology','Pharmacology','{"blanks":[{"id":"b1","options":["0.7 mL","1.44 mL","7.2 mL","14.4 mL"],"correct":"1.44 mL"},{"id":"b2","options":["16.2 mL/hr","32.4 mL/hr","36 mL/hr","64.8 mL/hr"],"correct":"32.4 mL/hr"}]}','RNMaster-Set15-Case','2'),
('Set15-RN-22','Pharmacological and Parenteral Therapies','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentences by choosing from the lists of options. The aPTT indicates the client is ___1___. Per protocol, after holding the infusion for 1 hour, the nurse should restart it at ___2___.','','','mL/hr An aPTT above 90 seconds is supratherapeutic. The new dose is 18 − 3 = 15 units/kg/hr × 90 kg = 1,350 units/hr ÷ 50 units/mL = 27 mL/hr. Platelets are stable, so HIT is not currently suggested.','Pharmacology','Pharmacology','{"blanks":[{"id":"b1","options":["over-anticoagulated with increased bleeding risk","therapeutically anticoagulated","under-anticoagulated with clotting risk","experiencing heparin-induced thrombocytopenia"],"correct":"over-anticoagulated with increased bleeding risk"},{"id":"b2","options":["27 mL/hr","29.7 mL/hr","32.4 mL/hr","36 mL/hr"],"correct":"27 mL/hr"}]}','RNMaster-Set15-Case','3'),
('Set15-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which actions should the nurse take? Select all that apply. ☐','Hold the heparin infusion for 1 hour per protocol ☐|Notify the provider of the aPTT and new bleeding ☐|Assess for other bleeding, including stool, emesis, and neurological changes ☐|Recheck the aPTT 6 hours after the rate change ☐|Instruct the client to use a soft-bristled toothbrush ☐|Administer a heparin rebolus ☐|Give an IM injection for the client''s back pain','A,B,C,D,E','The protocol directs holding and reducing the infusion, provider notification, and a repeat aPTT. Bleeding assessment and precautions reduce harm, and protamine may be needed for serious bleeding. A rebolus is for a low aPTT, and IM injections cause hematomas in anticoagulated clients.','Pharmacology','Management of Care','{}','RNMaster-Set15-Case','4'),
('Set15-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','Which action should the nurse take first?','Hold (stop) the heparin infusion|Decrease the infusion rate to 27 mL/hr immediately without holding|Draw a repeat aPTT|Complete an incident report','A','With a supratherapeutic aPTT and active bleeding, the protocol directs stopping the infusion for 1 hour first. The rate is then decreased when restarted.','Pharmacology','Pharmacology','{}','RNMaster-Set15-Case','5'),
('Set15-RN-25','Reduction of Risk Potential','Case study: Evaluate outcomes','matrix_grid','Over the next several days, the nurse monitors the client. For each finding, indicate whether it shows a desired outcome or requires immediate follow-up. Desired       Requires Finding','','','Desired: therapeutic aPTT, clear urine, SpO2 97% on room air, no bleeding. Follow-up: platelet drop over 50% with new swelling (possible HIT), sudden headache with confusion (possible intracranial bleed). A therapeutic aPTT, resolved hematuria, and improved oxygenation are expected. A platelet drop over 50% on days 5–10 with new thrombosis suggests HIT, requiring heparin to be stopped. Sudden headache with confusion suggests intracranial hemorrhage, an emergency. Answers: Set 16: Management of Care, Delegation, Legal and Ethical Issues','Pharmacology','Adult Health','{"columns":[{"id":"c1","label":"follow-up"}],"rows":[{"id":"r1","label":"aPTT 62 seconds 6 hours after the rate change","correct":"c1"},{"id":"r2","label":"Urine clear yellow","correct":"c1"},{"id":"r3","label":"SpO2 97% on room air","correct":"c1"},{"id":"r4","label":"No new bleeding noted","correct":"c1"},{"id":"r5","label":"Sudden severe headache and new confusion","correct":"c1"}]}','RNMaster-Set15-Case','6'),
('Set16-RN-20','Management of Care','Case study: Recognize cues','highlight','Highlight (circle) the report findings that require the RN''s prompt follow-up.','','','Room 2 shows respiratory distress. Room 5''s low potassium must be addressed before a loop diuretic, which will lower it further. The other findings are stable or expected.','Management of Care','Management of Care','{"segments":[{"id":"s1","text":"Room 2: SpO2 87% on 2 L/min","correct":true},{"id":"s2","text":"Room 2: RR 28 with accessory muscle use","correct":true},{"id":"s3","text":"Room 1: Pain 3/10 on PCA","correct":true},{"id":"s4","text":"Room 3: Ate 50% of dinner","correct":true},{"id":"s5","text":"Room 4: Fasting glucose 188 mg/dL","correct":true},{"id":"s6","text":"Room 5: Weight up 0.2 kg","correct":true},{"id":"s7","text":"Room 5: Potassium 3.1 mEq/L with IV furosemide due","correct":true}]}','RNMaster-Set16-Case','1'),
('Set16-RN-21','Management of Care','Case study: Analyze cues','matrix_grid','For each task, indicate the staff member most appropriate to perform it.','','','RNs perform assessments of unstable clients and initial teaching. LPNs/VNs give most routine medications to stable clients. APs perform standardized tasks such as feeding (without dysphagia) and ambulating stable clients.','Management of Care','Management of Care','{"columns":[{"id":"c1","label":"RN"},{"id":"c2","label":"LPN/VN"},{"id":"c3","label":"AP"}],"rows":[{"id":"r1","label":"Initial insulin teaching for Room 4","correct":"c2"},{"id":"r2","label":"Feeding assistance for Room 3","correct":"c1"},{"id":"r3","label":"Ambulating Room 1 in the hallway","correct":"c1"}]}','RNMaster-Set16-Case','2'),
('Set16-RN-22','Management of Care','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The RN should see ___1___ first, followed by ___2___.','','','Room 2 has an airway and breathing problem. Room 5 is next because hypokalemia must be addressed with the provider before the 0900 furosemide. Teaching for Room 4 is important but can be scheduled before afternoon discharge.','Management of Care','Management of Care','{"blanks":[{"id":"b1","options":["Room 2","Room 1","Room 3","Room 4"],"correct":"Room 2"},{"id":"b2","options":["Room 5","Room 1","Room 3","Room 4"],"correct":"Room 5"}]}','RNMaster-Set16-Case','3'),
('Set16-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which actions by the RN are appropriate? Select all that apply. ☐','Ask the AP to take vital signs on Rooms 1, 3, and 5 and report any values outside specific parameters ☐|Ask the LPN/VN to reinforce insulin teaching for Room 4 after the RN completes the initial teaching ☐|Contact the provider about Room 5''s potassium before the furosemide is given ☐|Tell the AP to report immediately if Room 3 coughs or chokes during meals ☐|Assign the LPN/VN to complete the assessment of Room 2 ☐|Ask the AP to decide whether Room 1''s pain medication is effective','A,B,C,D','Delegating stable-client tasks with clear reporting parameters, having the LPN/VN reinforce teaching, and clarifying the potassium issue are appropriate. Assessing an unstable client and evaluating medication effectiveness cannot be delegated.','Management of Care','Management of Care','{}','RNMaster-Set16-Case','4'),
('Set16-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','On entering Room 2, what should the RN do first?','Raise the head of the bed and assess the client''s airway, breathing, and oxygen delivery|Increase the oxygen to 6 L/min by nasal cannula|Call the provider before assessing|Obtain a sputum specimen','A','Positioning and a focused assessment, including checking that the cannula is in place and flowing, come first. Oxygen is then titrated to the prescribed target (often 88–92% in COPD), bronchodilators are given as prescribed, and the provider or respiratory therapist is notified with assessment data.','Management of Care','Adult Health','{}','RNMaster-Set16-Case','5'),
('Set16-RN-25','Management of Care','Case study: Evaluate outcomes','matrix_grid','At the end of the shift, the RN reviews the outcomes. For each finding, indicate whether the plan was effective or requires follow-up. Requires','','','Effective: Room 1 ambulation, Room 2 SpO2 90%, Room 4 return demonstration, Room 5 potassium managed. Follow-up: Room 3 coughing with meals, delayed report of low BP. Goals for mobility, oxygenation, teaching, and safe medication administration were met. Coughing during meals suggests aspiration and needs a swallow evaluation. The delayed report of hypotension shows a supervision and communication gap, which the RN must address with the AP. Answers: Set 17: Safety and Infection Control','Management of Care','Management of Care','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Room 1 ambulated three times","correct":"c1"},{"id":"r2","label":"Room 2 SpO2 90% on 2 L/min after a nebulizer treatment","correct":"c1"},{"id":"r3","label":"Room 4 demonstrated insulin self-injection correctly","correct":"c1"},{"id":"r4","label":"AP reports Room 3 coughed repeatedly during lunch","correct":"c1"},{"id":"r5","label":"AP mentions at 1830 that Room 1''s BP was 88/50 at 1000","correct":"c1"}]}','RNMaster-Set16-Case','6'),
('Set17-RN-20','Safety and Infection Control','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','An acute change in cognition with agitation suggests delirium and creates an immediate fall and injury risk. Urinary retention, hypoxemia, fever, and an anticholinergic medication are likely causes. BP is stable.','Safety & Infection Control','Safety & Infection Control','{"segments":[{"id":"s1","text":"Oriented to person only (yesterday oriented x3)","correct":false},{"id":"s2","text":"Trying to climb over the side rails","correct":true},{"id":"s3","text":"Pulling at the IV","correct":true},{"id":"s4","text":"Bladder scan 650 mL","correct":true},{"id":"s5","text":"SpO2 91% on room air","correct":true},{"id":"s6","text":"T 100.6°F (38.1°C)","correct":false},{"id":"s7","text":"Diphenhydramine 50 mg given at 2200","correct":true},{"id":"s8","text":"BP 118/70 mm Hg","correct":false}]}','RNMaster-Set17-Case','1'),
('Set17-RN-21','Safety and Infection Control','Case study: Analyze cues','matrix_grid','For each factor contributing to this client''s delirium and fall risk, indicate whether it is modifiable or nonmodifiable. Nonmodifiabl','','','Modifiable: diphenhydramine, urinary retention, hypoxemia, sensory aids not in use. Nonmodifiable: age, preexisting cognitive impairment. Delirium prevention targets modifiable causes: medications (especially anticholinergics), retention, hypoxia, infection, pain, and sensory deprivation. Age and baseline cognitive impairment increase risk but cannot be changed.','Safety & Infection Control','Safety & Infection Control','{"columns":[{"id":"c1","label":"Modifiable"}],"rows":[{"id":"r1","label":"Diphenhydramine use","correct":"c1"},{"id":"r2","label":"Urinary retention","correct":"c1"},{"id":"r3","label":"Hypoxemia","correct":"c1"},{"id":"r4","label":"Eyeglasses and hearing aids not in use","correct":"c1"},{"id":"r5","label":"Age of 82 years","correct":"c1"},{"id":"r6","label":"Preexisting mild cognitive impairment","correct":"c1"}]}','RNMaster-Set17-Case','2'),
('Set17-RN-22','Safety and Infection Control','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is most likely experiencing ___1___, and the priority is preventing ___2___.','','','Climbing over rails after hip surgery risks falls, fractures, dislocation, and device removal.','Safety & Infection Control','Safety & Infection Control','{"blanks":[{"id":"b1","options":["postoperative delirium","worsening Alzheimer''s disease","a primary psychotic disorder","alcohol withdrawal"],"correct":"postoperative delirium"},{"id":"b2","options":["falls and injury, including dislodging the IV and hip dislocation","constipation","pressure injury only","weight loss"],"correct":"falls and injury, including dislodging the IV and hip dislocation"}]}','RNMaster-Set17-Case','3'),
('Set17-RN-23','Safety and Infection Control','Case study: Generate solutions','multiple_response','Which interventions should the nurse implement? Select all that apply. ☐','Stay with the client or arrange continuous observation ☐|Put on the client''s eyeglasses and hearing aids and reorient calmly ☐|Lower the bed to the lowest position and activate a bed alarm ☐|Contact the provider about urinary retention, low SpO2, fever, and the diphenhydramine ☐|Raise all four side rails ☐|Give another dose of diphenhydramine to help the client sleep ☐|Apply wrist restraints as the first intervention','A,B,C,D','Supervision, sensory aids, reorientation, a low bed with an alarm, and treating underlying causes (catheterization, oxygen, evaluating for infection, stopping anticholinergics) are evidence-based. Four raised rails increase fall severity when clients climb over them. More anticholinergics worsen delirium, and restraints are a last resort.','Safety & Infection Control','Safety & Infection Control','{}','RNMaster-Set17-Case','4'),
('Set17-RN-24','Safety and Infection Control','Case study: Take action','single_best_answer','The nurse finds the client with one leg over the side rail. What should the nurse do first?','Leave to call the provider|Stay with the client, lower the bed, guide the client safely back, and call for assistance|Apply soft wrist restraints|Administer PRN haloperidol','B','Immediate physical safety comes first. The nurse does not leave a client at imminent risk of falling. After the client is safe, the nurse notifies the provider and addresses the causes.','Safety & Infection Control','Safety & Infection Control','{}','RNMaster-Set17-Case','5'),
('Set17-RN-25','Safety and Infection Control','Case study: Evaluate outcomes','matrix_grid','By morning, the nurse evaluates the plan. For each finding, indicate whether it shows the plan was effective or requires follow-up. Requires','','','Effective: improved orientation with sensory aids, SpO2 94%, retention relieved, no falls. Follow-up: alarm turned off, diphenhydramine still active. Improved cognition, oxygenation, and bladder emptying, with no injury, show effective care. A disabled alarm is a safety gap to address with staff. The provider should be asked to discontinue diphenhydramine to prevent recurrence. Answers: Set 18: Mixed Review 1','Safety & Infection Control','Safety & Infection Control','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"SpO2 94% on 1 L/min nasal cannula","correct":"c1"},{"id":"r2","label":"650 mL drained by straight catheterization; client now resting","correct":"c1"},{"id":"r3","label":"No falls; IV intact","correct":"c1"},{"id":"r4","label":"Bed alarm found turned off at 0500 by an unknown person","correct":"c1"},{"id":"r5","label":"Diphenhydramine still listed as an active PRN on the MAR","correct":"c1"}]}','RNMaster-Set17-Case','6'),
('Set18-RN-20','Health Promotion and Maintenance','Case study: Recognize cues','highlight','Highlight (circle) the findings that require follow-up.','','','Regular contractions with cervical change before 37 weeks indicate preterm labor, and a positive fetal fibronectin supports it. The UTI may be a trigger, and unknown GBS status requires prophylaxis. The FHR tracing and BP are reassuring.','Integrated','Fundamentals','{"segments":[{"id":"s1","text":"Contractions every 5 minutes","correct":true},{"id":"s2","text":"Cervix 2 cm dilated, 80% effaced","correct":false},{"id":"s3","text":"Fetal fibronectin positive","correct":true},{"id":"s4","text":"Positive nitrites and leukocyte esterase","correct":true},{"id":"s5","text":"GBS status unknown","correct":true},{"id":"s6","text":"FHR baseline 145/min with moderate variability","correct":false},{"id":"s7","text":"BP 118/72 mm Hg","correct":false}]}','RNMaster-Set18-Case','1'),
('Set18-RN-21','Health Promotion and Maintenance','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it supports a diagnosis of preterm labor or reflects reassuring fetal status. Supports        Reassuring Finding','','','Preterm labor: regular contractions, cervical change, positive fFN. Reassuring: normal baseline, moderate variability, accelerations. Preterm labor is diagnosed by regular contractions with cervical change before 37 weeks. A baseline of 110–160, moderate variability, and accelerations indicate a well-oxygenated fetus (Category I tracing).','Integrated','Fundamentals','{"columns":[{"id":"c1","label":"fetal status"}],"rows":[{"id":"r1","label":"Regular contractions every 5 minutes","correct":"c1"},{"id":"r2","label":"Cervical dilation and effacement","correct":"c1"},{"id":"r3","label":"Positive fetal fibronectin","correct":"c1"},{"id":"r4","label":"FHR baseline 145/min","correct":"c1"},{"id":"r5","label":"Moderate variability","correct":"c1"},{"id":"r6","label":"Accelerations present","correct":"c1"}]}','RNMaster-Set18-Case','2'),
('Set18-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is most likely experiencing ___1___, possibly triggered by ___2___.','','','urinary tract infection Braxton Hicks contractions do not cause cervical change. There is no bleeding, uterine rigidity, or hypertension to suggest abruption or preeclampsia. Genitourinary infections are a known trigger of preterm labor.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["preterm labor","Braxton Hicks contractions only","placental abruption","preeclampsia"],"correct":"preterm labor"},{"id":"b2","options":["a urinary tract infection","dehydration from exercise","a normal pregnancy change","hypoglycemia"],"correct":"a urinary tract infection"}]}','RNMaster-Set18-Case','3'),
('Set18-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Betamethasone IM, two doses 24 hours apart ☐|Magnesium sulfate IV for fetal neuroprotection ☐|Short-term tocolysis (such as nifedipine) to allow time for corticosteroids ☐|IV penicillin G for GBS prophylaxis ☐|Antibiotic treatment for the UTI ☐|Oral terbutaline for long-term maintenance tocolysis ☐|Strict bed rest for the remainder of pregnancy','A,B,C,D,E','Before 34 weeks, corticosteroids reduce neonatal respiratory distress and other complications. Magnesium before 32 weeks reduces the risk of cerebral palsy. Short-term tocolysis buys time for steroids, and GBS prophylaxis is given when status is unknown in preterm labor. The FDA warns against prolonged terbutaline use, and prolonged bed rest is not recommended.','Integrated','Pharmacology','{}','RNMaster-Set18-Case','4'),
('Set18-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','The nurse has prescriptions for all of the anticipated interventions. Which medication has the greatest impact on neonatal outcomes if delivery occurs?','Betamethasone|Acetaminophen|Nifedipine|Docusate','A','Antenatal corticosteroids accelerate fetal lung maturity and reduce neonatal respiratory distress, intraventricular hemorrhage, and mortality. They are most effective 24 hours to 7 days after the first dose, so timely administration is critical.','Integrated','Pharmacology','{}','RNMaster-Set18-Case','5'),
('Set18-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twenty-four hours later, the nurse reassesses the client. For each finding, indicate whether it shows the plan was effective or requires follow-up. Requires','','','Effective: fewer contractions, completed steroid course, reassuring FHR, adequate urine output. Follow-up: RR 10 with absent reflexes, new crackles with SpO2 90%. Decreased contractions, a completed steroid course, and a reassuring tracing show success. Respiratory depression with absent reflexes suggests magnesium toxicity. Crackles and hypoxemia suggest pulmonary edema, a known complication of magnesium and tocolytic therapy. Answers: Set 19: Mixed Review 2','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Contractions decreased to 1–2 per hour","correct":"c1"},{"id":"r2","label":"Second dose of betamethasone given on time","correct":"c1"},{"id":"r3","label":"FHR baseline 140/min with moderate variability","correct":"c1"},{"id":"r4","label":"Urine output 40 mL/hr","correct":"c1"},{"id":"r5","label":"RR 10/min with absent patellar reflexes","correct":"c1"},{"id":"r6","label":"New crackles with SpO2 90% on room air","correct":"c1"}]}','RNMaster-Set18-Case','6'),
('Set19-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','hallmarks of aortic dissection. Tachycardia increases shear stress on the aortic wall. The lungs, temperature, and SpO2 are normal.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"\"Tearing\" pain radiating to the back","correct":true},{"id":"s2","text":"BP difference of 46 mm Hg between the arms","correct":true},{"id":"s3","text":"New diastolic murmur","correct":true},{"id":"s4","text":"Weaker left radial pulse","correct":true},{"id":"s5","text":"HR 112/min","correct":false},{"id":"s6","text":"Lungs clear","correct":false},{"id":"s7","text":"T 98.4°F","correct":false},{"id":"s8","text":"SpO2 96% on room air","correct":false}]}','RNMaster-Set19-Case','1'),
('Set19-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it more strongly suggests aortic dissection or acute myocardial infarction. Aortic               Myocardial Finding','','','Dissection: tearing back pain, arm BP difference, aortic regurgitation murmur, unequal pulses. MI: ST elevation, crushing pressure with troponin rise. Distinguishing the two is critical, because anticoagulants and thrombolytics used for MI can be fatal in dissection. A dissection can occasionally involve a coronary artery and cause MI findings.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"infarction"}],"rows":[{"id":"r1","label":"Sudden tearing pain radiating to the back","correct":"c1"},{"id":"r2","label":"Significant BP difference between the arms","correct":"c1"},{"id":"r3","label":"New diastolic murmur of aortic regurgitation","correct":"c1"},{"id":"r4","label":"Unequal radial pulses","correct":"c1"},{"id":"r5","label":"ST elevation in two contiguous leads","correct":"c1"},{"id":"r6","label":"Crushing substernal pressure with elevated troponin","correct":"c1"}]}','RNMaster-Set19-Case','2'),
('Set19-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentences by choosing from the lists of options. The client has a ___1___. The greatest immediate threat is ___2___.','','','rupture, cardiac tamponade, or organ malperfusion Type A dissections involve the ascending aorta and carry high early mortality without surgery. They can rupture into the pericardium, occlude branch arteries, or cause acute aortic regurgitation.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["type A (ascending) aortic dissection requiring emergency surgery","type B dissection managed only with oral medications","stable angina","acute pericarditis"],"correct":"type A (ascending) aortic dissection requiring emergency surgery"},{"id":"b2","options":["aortic rupture, cardiac tamponade, or organ malperfusion","a pulmonary embolism","hypoglycemia","gastroesophageal reflux"],"correct":"aortic rupture, cardiac tamponade, or organ malperfusion"}]}','RNMaster-Set19-Case','3'),
('Set19-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV esmolol or labetalol to lower HR (goal about 60/min or less) and systolic BP (goal about 100–120 mm Hg) ☐|IV opioid analgesia ☐|Preparation for emergency surgical repair ☐|Two large-bore IVs and type and crossmatch ☐|Arterial line for continuous BP monitoring ☐|IV alteplase ☐|Chewable aspirin 325 mg and a heparin infusion','A,B,C,D,E','Management is rapid heart rate and BP control (a beta blocker first, then a vasodilator if needed), pain control that also reduces sympathetic surge, close monitoring, blood availability, and emergency surgery. Thrombolytics, aspirin, and heparin can cause catastrophic bleeding.','Integrated','Pharmacology','{}','RNMaster-Set19-Case','4'),
('Set19-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','Which medication should the nurse administer first?','Chewable aspirin 325 mg|IV esmolol|Heparin IV bolus|Nitroprusside infusion before any beta blocker','B','A beta blocker is given first to reduce heart rate and the force of ejection (shear stress). Starting a vasodilator alone first can cause reflex tachycardia and extend the dissection. Antiplatelet and anticoagulant drugs are contraindicated.','Integrated','Pharmacology','{}','RNMaster-Set19-Case','5'),
('Set19-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','While the client awaits transfer to the OR, the nurse reassesses. For each finding, indicate whether it shows the treatment was effective or requires immediate follow-up. Requires','','','Effective: HR 58, SBP 112, pain 3/10, urine output 50 mL/hr. Follow-up: new limb ischemia, signs of cardiac tamponade. Achieved HR and BP targets, pain control, and adequate renal perfusion show effective initial management. A pulseless limb indicates branch artery malperfusion. Hypotension with JVD and muffled heart sounds suggests rupture into the pericardium, which is immediately life-threatening. Answers: Set 20: Mixed Review 3','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"HR 58/min","correct":"c1"},{"id":"r2","label":"Systolic BP 112 mm Hg","correct":"c1"},{"id":"r3","label":"Pain decreased to 3/10","correct":"c1"},{"id":"r4","label":"Urine output 50 mL/hr","correct":"c1"},{"id":"r5","label":"New pallor and absent pulse in the left foot","correct":"c1"}]}','RNMaster-Set19-Case','6'),
('Set20-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Bradycardia with hypotension indicates shock, and a reduced vital capacity with shallow breathing warns of respiratory failure. The negative FAST, normal hemoglobin, and intact mental status argue against hemorrhage and brain injury.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"HR 48/min","correct":false},{"id":"s2","text":"BP 78/44 mm Hg (MAP 55)","correct":false},{"id":"s3","text":"Shallow, mainly abdominal breathing","correct":true},{"id":"s4","text":"Vital capacity 1.2 L","correct":true},{"id":"s5","text":"SpO2 93% on 2 L/min","correct":true},{"id":"s6","text":"FAST exam negative","correct":false},{"id":"s7","text":"Hemoglobin 14.2 g/dL","correct":false},{"id":"s8","text":"Alert and oriented x3","correct":false}]}','RNMaster-Set20-Case','1'),
('Set20-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more consistent with neurogenic shock or hypovolemic shock. Neurogenic   Hypovolemic Finding','','','Neurogenic: bradycardia, warm dry skin, normal Hgb with negative FAST. Hypovolemic: tachycardia, cool clammy skin, delayed refill with narrow pulse pressure. Cervical or high thoracic cord injury disrupts sympathetic outflow, causing vasodilation and unopposed vagal tone (hypotension with bradycardia and warm skin). Hemorrhage triggers compensatory tachycardia and vasoconstriction. Trauma clients can have both, so bleeding must be ruled out.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"shock"}],"rows":[{"id":"r1","label":"Bradycardia","correct":"c1"},{"id":"r2","label":"Warm, dry, flushed skin below the injury","correct":"c1"},{"id":"r3","label":"Tachycardia","correct":"c1"},{"id":"r4","label":"Cool, pale, clammy skin","correct":"c1"},{"id":"r5","label":"Normal hemoglobin with a negative FAST exam","correct":"c1"},{"id":"r6","label":"Delayed capillary refill with a narrow pulse pressure","correct":"c1"}]}','RNMaster-Set20-Case','2'),
('Set20-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentences by choosing from the lists of options. The client is experiencing ___1___. The most immediate threat to life is ___2___.','','','Cord swelling can extend upward toward the phrenic nerve (C3–C5). A falling vital capacity signals impending respiratory failure.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["neurogenic shock from loss of sympathetic tone","hemorrhagic shock","septic shock","cardiogenic shock"],"correct":"neurogenic shock from loss of sympathetic tone"},{"id":"b2","options":["respiratory failure from weakened respiratory muscles and possible ascending cord edema","pressure injury","urinary retention","hypoglycemia"],"correct":"respiratory failure from weakened respiratory muscles and possible ascending cord edema"}]}','RNMaster-Set20-Case','3'),
('Set20-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Maintain spinal immobilization and log-roll with in-line stabilization ☐|IV fluids, followed by a vasopressor such as norepinephrine to maintain the prescribed MAP (often 85–90 mm Hg) ☐|Atropine for symptomatic bradycardia ☐|Monitor vital capacity frequently and prepare for intubation ☐|Insert an indwelling urinary catheter ☐|Routine high-dose methylprednisolone ☐|Remove the cervical collar to assess the neck','A,B,C,D,E','Care focuses on preventing secondary cord injury, maintaining spinal cord perfusion (MAP goals of about 85–90 for several days are common), treating bradycardia, monitoring respiratory function, and managing the neurogenic bladder. High-dose steroids are no longer routinely recommended. The collar stays in place until cleared.','Integrated','Management of Care','{}','RNMaster-Set20-Case','4'),
('Set20-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','One hour later, the client''s vital capacity has decreased to 0.9 L, RR is 32/min, and the chest moves inward as the abdomen rises. What should the nurse do first?','Apply warm blankets|Call the airway team or provider immediately to prepare for intubation with manual in-line cervical stabilization|Insert the urinary catheter|Administer an oral analgesic','B','A vital capacity below about 15 mL/kg, rising RR, and paradoxical breathing indicate impending respiratory failure. Intubation is performed with in-line stabilization to prevent further cord injury.','Integrated','Adult Health','{}','RNMaster-Set20-Case','5'),
('Set20-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Forty-eight hours later, the intubated client is in the ICU. For each finding, indicate whether it shows effective management or requires follow-up. Requires','','','Effective: MAP 88, HR 64, urine output 45 mL/hr, normothermia. Follow-up: sacral stage 1 pressure injury, paralytic ileus signs. Meeting perfusion goals, a controlled heart rate, adequate renal perfusion, and normal temperature show effective management. A pressure injury and paralytic ileus are common complications of spinal cord injury and require prompt intervention, such as more frequent repositioning and NG decompression. Answers: Set 21: Mixed Review 4','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"MAP 88 mm Hg on norepinephrine","correct":"c1"},{"id":"r2","label":"HR 64/min","correct":"c1"},{"id":"r3","label":"Urine output 45 mL/hr via catheter","correct":"c1"},{"id":"r4","label":"Temperature 98.2°F (36.8°C) with warming measures","correct":"c1"},{"id":"r5","label":"Nonblanchable redness over the sacrum","correct":"c1"},{"id":"r6","label":"Absent bowel sounds with increasing abdominal distention","correct":"c1"}]}','RNMaster-Set20-Case','6'),
('Set21-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','leading to hypotension, tachycardia, and prerenal kidney injury. The near-normal pH, trace ketones, and SpO2 do not require immediate action.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Lethargic and disoriented","correct":false},{"id":"s2","text":"Glucose 986 mg/dL","correct":true},{"id":"s3","text":"Serum osmolality 362 mOsm/kg","correct":true},{"id":"s4","text":"BP 92/54 mm Hg with HR 118/min","correct":true},{"id":"s5","text":"Creatinine 2.1 mg/dL","correct":true},{"id":"s6","text":"Arterial pH 7.36","correct":false},{"id":"s7","text":"Serum ketones trace","correct":false},{"id":"s8","text":"SpO2 95% on room air","correct":false}]}','RNMaster-Set21-Case','1'),
('Set21-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each feature, indicate whether it is more characteristic of hyperosmolar hyperglycemic state (HHS) or diabetic ketoacidosis (DKA).','','','HHS: extreme glucose and osmolality, minimal ketones, pH above 7.30, gradual onset in older adults. DKA: Kussmaul respirations, fruity breath. In HHS, enough insulin is present to prevent significant ketogenesis, so acidosis is absent. The result is profound dehydration and hyperosmolality developing over days. DKA develops quickly with ketoacidosis.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"HHS"},{"id":"c2","label":"DKA"}],"rows":[{"id":"r1","label":"Absent or minimal ketones","correct":"c1"},{"id":"r2","label":"Arterial pH above 7.30","correct":"c1"},{"id":"r3","label":"Deep, rapid (Kussmaul) respirations","correct":"c1"},{"id":"r4","label":"Fruity breath odor","correct":"c1"},{"id":"r5","label":"Gradual onset over days in an older adult with type 2 diabetes","correct":"c1"}]}','RNMaster-Set21-Case','2'),
('Set21-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___ triggered by ___2___.','','','with decreased fluid intake Infection increases stress hormones and glucose, while poor intake and osmotic diuresis cause severe dehydration. Older adults often have an impaired thirst response. The normal pH and HCO3 make lactic acidosis unlikely.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["hyperosmolar hyperglycemic state","diabetic ketoacidosis","hypoglycemia","lactic acidosis from metformin"],"correct":"hyperosmolar hyperglycemic state"},{"id":"b2","options":["infection with decreased fluid intake","excess insulin","a high-protein diet","excessive exercise"],"correct":"infection with decreased fluid intake"}]}','RNMaster-Set21-Case','3'),
('Set21-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','0.9% sodium chloride IV to restore volume, then adjust based on corrected sodium ☐|IV regular insulin infusion after fluids are started and potassium is confirmed adequate ☐|Hourly blood glucose monitoring and frequent neurological checks ☐|Add dextrose to IV fluids when glucose falls to about 300 mg/dL ☐|IV antibiotics for the urinary tract infection ☐|Sodium bicarbonate IV ☐|Lowering glucose to normal within the first 2 hours','A,B,C,D,E','HHS management centers on aggressive fluid replacement, a controlled insulin infusion, close monitoring, dextrose once glucose reaches about 300 mg/dL, and treating the trigger. Bicarbonate is not indicated without acidosis, and rapid glucose correction risks cerebral edema.','Integrated','Pharmacology','{}','RNMaster-Set21-Case','4'),
('Set21-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Two hours after treatment begins, the glucose has dropped from 986 to 520 mg/dL. What should the nurse do?','Continue the current rates since the glucose is still high|Notify the provider, because the glucose is falling faster than the recommended rate|Increase the insulin infusion rate|Stop IV fluids','B','Glucose should generally fall about 50–75 mg/dL per hour. A drop of about 233 mg/dL per hour increases the risk of rapid osmolality shifts and cerebral edema, so rates need adjustment.','Integrated','Adult Health','{}','RNMaster-Set21-Case','5'),
('Set21-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Eighteen hours after admission, the nurse reassesses the client. For each finding, indicate whether it shows the treatment was effective or requires follow-up. Requires','','','Effective: glucose 280 with dextrose, osmolality 304, urine output 60 mL/hr, oriented. Follow-up: rising sodium, seizure. Controlled glucose, improving osmolality, restored perfusion, and improved mental status show response. A rising sodium indicates free water deficit requiring fluid adjustment, and a seizure suggests a neurological complication such as cerebral edema. Answers: Set 22: Mixed Review 5','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Glucose 280 mg/dL with dextrose added to IV fluids","correct":"c1"},{"id":"r2","label":"Serum osmolality 304 mOsm/kg","correct":"c1"},{"id":"r3","label":"Urine output 60 mL/hr","correct":"c1"},{"id":"r4","label":"Oriented to person, place, and time","correct":"c1"},{"id":"r5","label":"Sodium 158 mEq/L","correct":"c1"},{"id":"r6","label":"New generalized tonic-clonic seizure","correct":"c1"}]}','RNMaster-Set21-Case','6')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline,response_config,caseid,case_sequence) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method,case_set_id,case_study_id,case_sequence) values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Evaluate each response against the source key and clinical task.','Interpret the case cues and respond in the native NCLEX item format.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,r.response_config::jsonb,case when r.item_type='multiple_response' then 'plus_minus' when r.item_type='single_best_answer' then 'zero_one' else 'rationale' end,nullif(r.caseid,''),nullif(r.caseid,''),case when r.case_sequence::int>0 then r.case_sequence::int else null end) on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,response_config=excluded.response_config,source_id=excluded.source_id,case_set_id=excluded.case_set_id,case_study_id=excluded.case_study_id,case_sequence=excluded.case_sequence,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid;
 if r.item_type in ('single_best_answer','multiple_response') then keyarr:=string_to_array(r.keys,','); n:=0; for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop; select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid; if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source answer mapped to native response model; clinical review pending.' where id=qvid;
end loop; end $$; commit;